import {isAdmin,canShift,reportTotals,paymentTotals,orderTotal} from './permissions.js';
import {managementPages,proposalPanel} from './management-ui.js';
import {same} from './sync-state.js';
import {createCloudStore,LOCAL_KEY} from './cloud-store.js';
const seed = [
 ['Cà phê','Cà phê đá',20000],['Cà phê','Cà phê sữa',22000],['Cà phê','Bạc xỉu',25000],['Cà phê','Sâm dứa sữa',25000],['Cà phê','Cà phê muối',29000],['Cà phê','Cà phê cốt dừa',29000],['Cà phê','Cà phê lá dứa',29000],['Cà phê','Cacao đá',29000],
 ['Trà','Trà Lipton chanh',25000],['Trà','Trà gừng',25000],['Trà','Trà đào cam sả',32000],['Trà','Trà vải hoa hồng',32000],['Trà','Trà dâu Nam Mỹ',32000],['Trà','Trà sen vàng',35000],['Trà','Trà xoài macchiato',35000],['Trà','Trà lài kem cheese',35000],['Trà','Trà sữa Olong',35000],['Trà','Trà sữa lá dứa',35000],['Trà','Lục trà mật ong',35000],['Trà','Trà đường',15000],
 ['Nước ép','Ép cam',28000],['Nước ép','Ép dưa hấu',28000],['Nước ép','Ép thơm',28000],['Nước ép','Ép chanh dây',28000],['Nước ép','Ép chanh tươi',28000],['Nước ép','Tắc xí muội',28000],['Nước ép','Ép cam - carrot',33000],['Nước ép','Ép táo thơm',33000],
 ['Sinh tố','Sinh tố việt quất',35000],['Sinh tố','Sinh tố phúc bồn tử',35000],['Sinh tố','Sinh tố dâu',35000],['Sinh tố','Sinh tố sữa dừa',35000],['Sinh tố','Sinh tố theo mùa',35000],
 ['Đá xay & Yaourt','Yaourt đá',29000],['Đá xay & Yaourt','Yaourt lá dứa',32000],['Đá xay & Yaourt','Yaourt đào',32000],['Đá xay & Yaourt','Yaourt chanh dây',32000],['Đá xay & Yaourt','Yaourt việt quất',32000],['Đá xay & Yaourt','Matcha đá xay',39000],['Đá xay & Yaourt','Mocha đá xay',39000],['Đá xay & Yaourt','Chocolate đá xay',39000],['Đá xay & Yaourt','Cookie đá xay',39000],['Đá xay & Yaourt','Dừa sáp',39000],['Đá xay & Yaourt','Dừa lạnh',25000],
 ['Soda & Khác','Soda blue',35000],['Soda & Khác','Soda chanh',29000],['Soda & Khác','Soda việt quất',35000],['Soda & Khác','Soda chanh dây',35000],['Soda & Khác','Coca / 7Up / Sting / Olong',22000],['Soda & Khác','Bò húc',25000],['Soda & Khác','Nước suối',15000]
].map(([category,name,price],i)=>({id:`m${i}`,category,name,price}));
const KEY=LOCAL_KEY;
const store=createCloudStore(seed,{
 onData:value=>{db=value;if(!modal||modal==='cloud')render();},
 onStatus:()=>{if(!store.hasSession()||document.querySelector('.auth-screen')){if(!store.hasSession()){modal=null;draft=null;page='dashboard';}render();return;}renderCloudStatus();if(!access()||document.querySelector('.access-screen')){modal=null;draft=null;render();return;}if(draft&&!allowedShift(draft.day||today,draft.shift||shift)){modal=null;draft=null;render();return;}if(modal==='cloud')renderOverlay();}
});
let db=store.read();
const money=n=>new Intl.NumberFormat('vi-VN').format(n)+' ₫';
const dateKey=(date=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Ho_Chi_Minh',year:'numeric',month:'2-digit',day:'2-digit'}).format(date);
const today=dateKey();
let page='dashboard', shift=Number(sessionStorage.getItem('shift')||1), category='Tất cả',query='',historyQuery='',historyDate='',historyShift='', draft=null, modal=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase();
const icons={dashboard:'▦',history:'◷',menu:'☷',shifts:'◴',revenue:'↗',team:'♙',audit:'☷'};
const access=()=>store.status().access;
const admin=()=>isAdmin(access());
const actor=()=>({id:access()?.userId,email:access()?.email});
const allowedShift=(day,s)=>canShift(access(),day,s);
let report={day:today,period:'day',shift:''},auditRows=[],auditQuery='';
const navItems=()=>[['dashboard','Quầy bán hàng'],['history','Lịch sử đơn hàng'],['menu','Thực đơn'],['shifts','Quản lý ca'],['revenue','Doanh thu'],...(admin()?[['team','Nhân viên'],['audit','Nhật ký']]:[])];
const management=()=>managementPages({db,access:access(),esc,money,today,report,auditRows,auditQuery});
async function manage(action,payload){const result=await store.manage(action,payload);if(!result.ok){toast(result.message);return false;}render();toast('Đã lưu thay đổi.');return true;}
const paymentLabel=o=>o.paymentMethod==='cash'?'Tiền mặt':o.paymentMethod==='transfer'?'Chuyển khoản':'Chưa ghi nhận phương thức';
// Replace this local asset with the shop's real payment QR when available.
const PAYMENT_QR='/payment-qr.svg';
const total=o=>o.items.reduce((s,i)=>s+i.price*i.qty,0);
const orders=(day=today,s=shift)=>db.orders.filter(o=>o.day===day&&o.shift===s);
const closed=()=>db.closings.some(c=>c.day===today&&c.shift===shift);
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function toast(message){document.querySelector('#toast').textContent=message;document.querySelector('#toast').classList.add('show');setTimeout(()=>document.querySelector('#toast').classList.remove('show'),3000);}
function persist(next){const result=store.persist(next);if(!result.ok)toast(result.message);db=store.read();return result.ok;}
function cloudLabel(){const state=store.status();return ({local:'Lưu trên máy',login:'Đăng nhập đồng bộ',loading:'Đang tải dữ liệu',syncing:'Đang đồng bộ',synced:'Đã đồng bộ',pending:'Chờ đồng bộ',conflict:'Cần đối chiếu',error:'Chưa đồng bộ','config-error':'Chưa cấu hình'})[state.mode]||'Lưu trên máy';}
function renderCloudStatus(){
 const state=store.status();
 document.querySelectorAll('[data-cloud-label]').forEach(el=>el.textContent=cloudLabel());
 document.querySelectorAll('.cloud-indicator').forEach(el=>el.classList.toggle('cloud-warning',['pending','error','conflict','config-error'].includes(state.mode)));
 const hint=document.querySelector('[data-cloud-hint]');if(hint)hint.textContent=store.hasSession()?'Dữ liệu dùng chung trong quán':'Dữ liệu riêng trên thiết bị';
}
function cloudDialog(){
 const state=store.status(),legacy=store.legacy(),signedIn=store.hasSession();
 return `<div class="small-dialog cloud-dialog"><div class="dialog-heading"><h2>Lưu trữ & đồng bộ</h2><button class="icon-button" data-action="dismiss" aria-label="Đóng">×</button></div><div class="cloud-summary"><span class="cloud-symbol">☁</span><div><h3>${cloudLabel()}</h3><p>${esc(state.message||'Dữ liệu đang được lưu trên trình duyệt này.')}</p></div></div>${signedIn?`<p class="cloud-account">${esc(state.email)}</p><p class="muted">Dữ liệu quán dùng chung trên nhiều thiết bị; quyền truy cập theo vai trò và ca được phân công. Thay đổi trên máy được giữ khi mất mạng.</p>${state.lastSync?`<p class="muted">Đồng bộ lúc ${new Date(state.lastSync).toLocaleString('vi-VN')}</p>`:''}<button class="primary full" data-action="cloud-sync">↻ Đồng bộ ngay</button>${state.mode==='conflict'?`<button class="secondary full" data-action="export">↓ Xuất bản trên máy để đối chiếu</button><button class="secondary full" data-action="cloud-remote">Dùng bản trên database</button><p class="muted">Khi chọn bản database, bản trên máy trước đó được giữ trong bản sao cục bộ.</p>`:''}${admin()&&legacy?`<button class="secondary full" data-action="export-legacy">↓ Xuất bản sao dữ liệu cũ trên máy</button>`:''}${admin()&&legacy&& !db.orders.length&&!db.closings.length?`<div class="cloud-import"><h3>Dữ liệu cũ trên máy</h3><p>${legacy.orders?.length||0} đơn · ${legacy.closings?.length||0} báo cáo ca. Chưa tự động nhập vào tài khoản.</p><button class="secondary full" data-action="cloud-import">Nhập dữ liệu cũ vào tài khoản</button></div>`:''}<button class="secondary full" data-action="change-password">Đổi mật khẩu</button><button class="secondary full" data-action="cloud-logout">Đăng xuất</button>`:state.configured?`<p class="muted">Đăng nhập tài khoản được tạo trong Supabase để lưu dữ liệu online. Dữ liệu cũ trên máy vẫn được giữ riêng.</p><form id="cloud-login"><label>Email<input name="email" type="email" required autocomplete="username" placeholder="Email tài khoản"></label><label for="login-password">Mật khẩu</label><div class="password-field"><input id="login-password" name="password" type="password" required autocomplete="current-password" placeholder="Mật khẩu tài khoản"><button type="button" class="password-toggle" data-action="toggle-password" aria-label="Hiện mật khẩu" aria-controls="login-password" aria-pressed="false">Hiện</button></div><p id="cloud-login-error" class="form-error" role="alert"></p><button class="primary full" type="submit">Đăng nhập & đồng bộ</button></form>`:`<p class="note">Đồng bộ Supabase chưa được bật cho bản ứng dụng này. Bạn vẫn có thể bán hàng và xuất dữ liệu trên máy.</p>`}</div>`;
}
function loginForm(){return `<form id="cloud-login"><label for="login-email">Email</label><input id="login-email" name="email" type="email" required autocomplete="username" placeholder="Email của bạn"><label for="login-password">Mật khẩu</label><div class="password-field"><input id="login-password" name="password" type="password" required autocomplete="current-password" placeholder="Nhập mật khẩu"><button type="button" class="password-toggle" data-action="toggle-password" aria-label="Hiện mật khẩu" aria-controls="login-password" aria-pressed="false">Hiện</button></div><p id="cloud-login-error" class="form-error" role="alert"></p><button class="primary full" type="submit" aria-label="Đăng nhập">Đăng nhập <span aria-hidden="true">↗</span></button></form>`;}
function authScreen(){
 const state=store.status(),loading=!state.authReady;
 return `<main class="auth-screen"><section class="auth-story" aria-label="Lam An Coffee"><div class="auth-wordmark"><img src="/lam-an-logo.png" alt="Logo Lam An"><div>Lam An<small>COFFEE SHOP</small></div></div><div class="auth-story-content"><span class="eyebrow">MỘT CHÚT CÀ PHÊ, MỘT NGÀY THẬT TỐT</span><h1>Chăm chút từng ly.<br>Trọn vẹn mỗi ngày.</h1><p>Một góc nhỏ để quản lý đơn hàng,<br>đón khách và bắt đầu những ca làm thật vui.</p><div class="auth-coffee-art" aria-hidden="true"><div class="auth-saucer"></div><div class="auth-cup">✳</div><span class="auth-steam">∿</span><i>✦</i></div></div><span class="auth-story-footer">LAM AN · QUẦY BÁN HÀNG</span></section><section class="auth-entry"><div class="auth-mobile-brand"><img src="/lam-an-logo.png" alt="Lam An"><b>Lam An</b><span>COFFEE SHOP</span></div><div class="auth-card"><span class="eyebrow">CHÀO MỪNG BẠN TRỞ LẠI</span><h2>Đăng nhập</h2><p class="auth-intro">Đăng nhập để bắt đầu ca làm và quản lý quán của bạn.</p>${loading?`<div class="auth-loading" role="status"><span></span>Đang kiểm tra phiên đăng nhập…</div>`:state.configured?`${loginForm()}<p class="auth-help">Sử dụng email và mật khẩu tài khoản được quản lý quán cấp.</p>`:`<div class="note" role="alert">Ứng dụng chưa được cấu hình kết nối đăng nhập. Vui lòng liên hệ quản lý để thiết lập Supabase và triển khai lại.</div>`}<div class="auth-privacy"><span>◈</span> Dữ liệu được bảo vệ theo tài khoản của bạn</div></div><footer class="auth-footer">Lam An POS <span>Chúc bạn một ca làm thật tốt ✳</span></footer></section></main><div id="overlay-root"></div>`;
}
function header(){return `<aside class="sidebar"><a class="brand" href="#" aria-label="Lam An"><img class="brand-logo" src="/lam-an-logo.png" alt="Logo Lam An Coffee shop"><div>Lam An<small>COFFEE SHOP</small></div></a><div class="workspace-label">${admin()?'ADMIN · QUẢN LÝ QUÁN':'NHÂN VIÊN · CA ĐƯỢC PHÂN CÔNG'}</div><nav>${navItems().map(([id,label])=>`<button class="nav-item ${page===id?'active':''}" data-page="${id}"><span>${icons[id]}</span>${label}${page===id?'<i></i>':''}</button>`).join('')}</nav><button class="sidebar-bottom cloud-indicator" data-action="cloud"><div class="local-dot"></div><div><span data-cloud-label>${cloudLabel()}</span><small data-cloud-hint>${store.hasSession()?'Dữ liệu dùng chung trong quán':'Dữ liệu riêng trên thiết bị'}</small></div><span>↗</span></button><div class="sidebar-footer">Lam An POS <span>v1.0</span></div></aside><div class="main"><header class="topbar"><div class="breadcrumb">Lam An Coffee <span>/</span> <b>${{dashboard:'Quầy bán hàng',history:'Lịch sử đơn hàng',menu:'Thực đơn',shifts:'Quản lý ca',revenue:'Doanh thu',team:'Nhân viên',audit:'Nhật ký'}[page]}</b></div><div class="topbar-right"><button class="saved cloud-indicator" data-action="cloud"><i></i><span data-cloud-label>${cloudLabel()}</span></button><img class="avatar brand-avatar" src="/lam-an-logo.png" alt="Lam An"></div></header>`;}
function pageHeading(eyebrow,title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
function orderCard(o){return `<button class="order-card" data-detail="${o.id}"><div class="order-card-top"><span class="order-icon">${o.customer?'♙':'▤'}</span><span class="badge ${o.status==='paid'?'paid':''}">${o.status==='cancelled'?'Đã hủy':o.status==='paid'?'Đã thanh toán':'Đang phục vụ'}</span></div><h3>${esc(o.label)}</h3><div class="order-meta">#${o.code} <span>·</span> ${new Date(o.created).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}</div><div class="order-summary">${esc(o.items.map(i=>`${i.qty} ${i.name}`).join(', '))}</div><div class="order-card-bottom"><span>${o.items.reduce((s,i)=>s+i.qty,0)} món</span><strong>${money(total(o))}</strong></div></button>`;}
function dashboard(){if(!admin()&&!allowedShift(today,shift))return `${pageHeading('CA LÀM CỦA BẠN','Chưa có ca hôm nay','Liên hệ admin để được phân ca trước khi tạo đơn.')}<div class="empty-state"><h3>Lịch phân ca</h3>${access().assignments.map(a=>`<p>${a.day} · Ca ${a.shift}</p>`).join('')||'<p>Chưa có lịch làm việc.</p>'}</div>`;const list=orders(),paid=list.filter(o=>o.status==='paid'),active=list.filter(o=>o.status==='open');return `${pageHeading('MỘT NGÀY THẬT NHIỀU NĂNG LƯỢNG','Chào bạn, sẵn sàng đón khách?','Một ly cà phê ngon, một ngày làm việc trọn vẹn.',`<button class="primary" data-action="new">＋ Tạo đơn mới</button>`)}<div class="day-strip"><div>☀ <b>${new Date().toLocaleDateString('vi-VN',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Asia/Ho_Chi_Minh'})}</b></div><div class="shift-switch">${[1,2,3].filter(s=>allowedShift(today,s)).map(s=>`<button data-shift="${s}" class="${shift===s?'selected':''}">Ca ${s}</button>`).join('')}</div><span class="shift-state"><i></i> ${closed()?'Ca đã kết thúc':'Ca đang mở'}</span></div><div class="stats"><div class="stat"><div class="stat-label">Doanh thu ca <span>↗</span></div><div class="stat-value">${money(paid.reduce((s,o)=>s+total(o),0))}</div><small>Đã thanh toán trong ca ${shift}</small></div><div class="stat"><div class="stat-label">Tổng đơn hàng <span>▤</span></div><div class="stat-value">${list.length.toString().padStart(2,'0')} <em>đơn</em></div><small>${paid.length} đơn đã thanh toán</small></div><div class="stat"><div class="stat-label">Đang phục vụ <span>◷</span></div><div class="stat-value">${active.length.toString().padStart(2,'0')} <em>đơn</em></div><small>Cần thanh toán ${money(active.reduce((s,o)=>s+total(o),0))}</small></div></div><section><div class="section-heading"><div><h2>Đơn hàng trong ca <span>${list.length}</span></h2><p>Theo dõi và quản lý các đơn hàng của bạn</p></div><button class="secondary" data-page="shifts">◴ Kết ca</button></div>${list.length?`<div class="order-grid">${[...list].reverse().map(orderCard).join('')}<button class="add-card" data-action="new"><span>＋</span>Tạo đơn mới<small>Thêm một niềm vui mới</small></button></div>`:`<div class="empty-state"><div class="empty-illustration">☕<span>✦</span></div><h3>Quầy đã sẵn sàng, chờ đơn đầu tiên</h3><p>Tạo đơn mới, chọn món yêu thích và bắt đầu một ca thật tốt.</p><button class="primary" data-action="new">＋ Tạo đơn đầu tiên</button></div>`}</section><div class="gentle-note"><span>✳</span><div><b>Mọi đơn hàng đều được tự động lưu</b><p>${store.hasSession()?'Thay đổi được lưu trên máy và gửi lên Supabase. Chạm trạng thái phía trên để kiểm tra đồng bộ.':'Bạn có thể đóng trang và quay lại trên cùng trình duyệt. Đăng nhập để bật đồng bộ giữa các thiết bị.'}</p></div><span class="note-decoration">☕</span></div>`;}
function menuCards(edit=false){const list=db.menu.filter(m=>(category==='Tất cả'||m.category===category)&&normalize(m.name).includes(normalize(query)));return `<div class="category-tabs">${['Tất cả',...new Set(db.menu.map(m=>m.category))].map(c=>`<button data-category="${esc(c)}" class="${category===c?'selected':''}">${esc(c)}</button>`).join('')}</div><div class="menu-grid">${list.map((m,i)=>`<button class="menu-card" ${edit?`data-edit-menu="${m.id}"`:`data-add="${m.id}"`}><div class="drink-art art-${['Cà phê','Trà','Nước ép','Sinh tố','Đá xay & Yaourt','Soda & Khác'].indexOf(m.category)}"><div class="drink-cup"><span></span></div><i>✦</i></div><div class="menu-card-info"><small>${esc(m.category)}</small><h3>${esc(m.name)}</h3><div><b>${money(m.price)}</b><span class="menu-plus">${edit?'✎':'＋'}</span></div></div></button>`).join('')}</div>${list.length?'':`<div class="mini-empty">Không tìm thấy món “${esc(query)}”<button class="secondary" data-action="add-menu">＋ Thêm món & giá</button></div>`}`;}
function menuPage(){return `${pageHeading('HƯƠNG VỊ NHÀ LAM AN','Thực đơn','Những món quen thuộc, sẵn sàng cho từng đơn hàng.',`<button class="primary" data-action="add-menu">＋ Thêm món mới</button>`)}<div class="search-wrap"><span>⌕</span><input id="menu-search" placeholder="Tìm tên món trong thực đơn…" value="${esc(query)}" aria-label="Tìm món"></div><div id="menu-results">${menuCards(true)}</div><p class="muted">Giá được tham khảo từ menu quán · Chạm vào món để chỉnh sửa tên và giá.</p>${proposalPanel(access(),esc,money)}`;}
function history(){let list=db.orders.filter(o=>(!historyDate||o.day===historyDate)&&(!historyShift||o.shift===Number(historyShift))&&normalize(`${o.label} ${o.code} ${o.items.map(i=>i.name).join(' ')}`).includes(normalize(historyQuery))).sort((a,b)=>b.created.localeCompare(a.created));return `${pageHeading('MỖI ĐƠN HÀNG, MỘT CÂU CHUYỆN','Lịch sử đơn hàng','Tìm lại đơn hàng theo tên khách, số đơn hoặc món đã gọi.',admin()?`<button class="secondary" data-action="export">↓ Xuất dữ liệu</button>`:'')}<div class="history-filters"><div class="search-wrap"><span>⌕</span><input id="history-search" placeholder="Tìm khách hàng, số đơn, món…" aria-label="Tìm đơn hàng" value="${esc(historyQuery)}"></div><input type="date" id="history-date" aria-label="Ngày đơn hàng" value="${historyDate}"><select id="history-shift" aria-label="Lọc ca"><option value="">Tất cả ca</option>${[1,2,3].map(s=>`<option value="${s}" ${historyShift==s?'selected':''}>Ca ${s}</option>`).join('')}</select></div><div class="section-heading"><h2>${list.length} đơn hàng</h2><span class="muted">Đã thanh toán: ${money(list.filter(o=>o.status==='paid').reduce((s,o)=>s+total(o),0))}</span></div>${list.length?`<div class="history-list">${list.map(o=>`<button class="history-row" data-detail="${o.id}"><span class="order-icon">▤</span><div><h3>${esc(o.label)}</h3><small>#${o.code} · ${o.day.split('-').reverse().join('/')} · Ca ${o.shift}</small></div><span class="history-items">${esc(o.items.map(i=>`${i.qty} ${i.name}`).join(', '))}</span><span class="badge ${o.status==='paid'?'paid':''}">${o.status==='cancelled'?'Đã hủy':o.status==='paid'?`Đã thanh toán · ${paymentLabel(o)}`:'Đang phục vụ'}</span><strong>${money(total(o))}</strong><span>›</span></button>`).join('')}</div>`:'<div class="empty-state compact"><div class="empty-illustration">◷</div><h3>Chưa có đơn hàng phù hợp</h3><p>Các đơn hàng đã lưu sẽ xuất hiện ở đây.</p></div>'}`;}
function shiftsPage(){const dayOrders=db.orders.filter(o=>o.day===today),dayClosings=db.closings.filter(c=>c.day===today),r=reportTotals(dayOrders,dayClosings);return `${pageHeading('GỌN GÀNG SAU MỖI CA','Quản lý ca làm việc',admin()?'Đối chiếu tiền thực thu và quản lý cả ba ca.':'Bạn chỉ quản lý các ca được phân công.')}<div class="daily-total"><div><span>${admin()?'TỔNG DOANH THU HÔM NAY':'DOANH THU CÁC CA ĐƯỢC PHÂN CÔNG'}</span><h2>${money(r.revenue)}</h2><p>${dayOrders.length} đơn · ${r.cancelled} đơn hủy · ${today.split('-').reverse().join('/')}</p></div><span>◴</span></div><div class="shift-grid">${[1,2,3].filter(n=>allowedShift(today,n)).map(n=>{const list=orders(today,n),closing=db.closings.find(c=>c.day===today&&c.shift===n),r=reportTotals(list,closing?[closing]:[]);return `<div class="shift-card"><div class="section-heading"><h2>Ca ${n}</h2><span class="badge ${closing?'paid':''}">${closing?'Đã kết ca':'Đang mở'}</span></div><div class="shift-amount">${money(r.revenue)}</div><p>${list.length} đơn · ${list.filter(o=>o.status==='open').length} chưa thanh toán</p>${closing?`<div class="closing-time">Kết lúc ${new Date(closing.at).toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit'})}<br>Doanh thu đã chốt: ${money(closing.revenue)}${closing.originalRevenue!==undefined?`<br>Đã điều chỉnh · Gốc: ${money(closing.originalRevenue)}`:''}<br>Tiền mặt thực đếm: ${closing.actualCash==null?'Chưa đối chiếu':money(closing.actualCash)}<br>Chênh lệch: ${closing.discrepancy==null?'—':money(closing.discrepancy)}<br>${esc(closing.closedByEmail||'Dữ liệu cũ')}</div>${admin()?`<button class="secondary full" data-adjust-shift="${n}" data-day="${today}">Điều chỉnh ca</button>`:''}`:`<button class="secondary full" data-close-shift="${n}">Kết ca ${n} ↗</button>`}</div>`;}).join('')||'<p class="note">Chưa có ca được phân công hôm nay.</p>'}</div><div class="section-heading"><h2>Lịch sử kết ca</h2></div><div class="history-list">${[...db.closings].reverse().map(c=>`<div class="closing-row"><div><b>Ca ${c.shift}</b><small>${c.day.split('-').reverse().join('/')}</small>${c.originalRevenue!==undefined?`<small>Đã điều chỉnh từ ${money(c.originalRevenue)}</small>`:''}<small>${esc(c.closedByEmail||'Dữ liệu cũ')}</small></div><span>${c.count} đơn đã thanh toán</span><strong>${money(c.revenue)}</strong>${admin()?`<button class="secondary" data-adjust-shift="${c.shift}" data-day="${c.day}">Điều chỉnh</button>`:''}</div>`).join('')||'<div class="mini-empty">Chưa có ca nào được kết.</div>'}</div>`;}
function closeShiftDialog(){const list=orders(today,closingShift),open=list.filter(o=>o.status==='open'),r=reportTotals(list,[]);return `<div class="small-dialog"><div class="dialog-heading"><h2>Kết ca ${closingShift}</h2><button class="icon-button" data-action="dismiss" aria-label="Đóng">×</button></div><p class="muted">${today} · Kiểm tra tiền thực thu trước khi kết ca.</p><div class="cart-grand"><span>Doanh thu ca</span><strong>${money(r.revenue)}</strong></div><p>${list.length} đơn hàng · ${r.paid} đã thanh toán · ${r.cancelled} hủy</p>${open.length?`<p class="warning">Còn ${open.length} đơn chưa thanh toán. Vui lòng thanh toán trước khi kết ca.</p><button class="secondary full" data-action="go-open">Xem đơn chưa thanh toán</button>`:`<p class="note">Tiền mặt hệ thống: ${money(r.cash)}<br>Chuyển khoản: ${money(r.transfer)}</p><label>Tiền mặt thực đếm (VNĐ)<input id="close-actual-cash" type="number" min="0" step="1000" value="${Math.max(0,r.cash)}"></label><label>Ghi chú đối chiếu<input id="close-note" maxlength="300" placeholder="Bắt buộc nếu tiền mặt chênh lệch"></label><p class="muted">Ca đã kết không nhận đơn mới. Đồng bộ các thiết bị trước khi chốt.</p><button class="primary full" data-action="confirm-close">Xác nhận kết ca</button>`}</div>`;}
function cancelDialog(){const o=db.orders.find(o=>o.id===detailId);if(!o)return '';return `<form id="cancel-form" class="small-dialog"><div class="dialog-heading"><h2>Hủy đơn ${esc(o.label)}</h2><button type="button" class="icon-button" data-action="dismiss" aria-label="Đóng">×</button></div><p class="muted">Đơn và lịch sử vẫn được giữ lại. Đơn hủy được loại khỏi doanh thu.</p><label>Lý do hủy<input name="reason" required minlength="3" maxlength="300" placeholder="Nhập lý do"></label>${o.status==='paid'?`<p class="warning">Cần hoàn ${money(total(o))} theo các phương thức đã thu.</p><label class="check-label"><input name="refund" type="checkbox" required> Đã hoàn đủ tiền cho khách</label>`:''}<button class="primary full" type="submit">Xác nhận hủy đơn</button></form>`;}
function adjustDialog(){return `<form id="adjust-form" class="small-dialog"><div class="dialog-heading"><h2>Điều chỉnh ca ${adjustTarget.shift}</h2><button type="button" class="icon-button" data-action="dismiss" aria-label="Đóng">×</button></div><p class="muted">${adjustTarget.day} · Giữ báo cáo gốc và lưu người điều chỉnh.</p><label>Số tiền điều chỉnh (VNĐ)<input name="amount" type="number" required step="1000" placeholder="Dương để tăng, âm để giảm"></label><label>Phương thức<select name="method"><option value="cash">Tiền mặt</option><option value="transfer">Chuyển khoản</option></select></label><label>Lý do<input name="reason" required minlength="3" maxlength="300"></label><button class="primary full" type="submit">Lưu điều chỉnh</button></form>`;}

function render(){if(!store.status().authReady||!store.hasSession()){document.querySelector('#app').innerHTML=authScreen();return;}if(!access()){document.querySelector('#app').innerHTML=`<main class="access-screen"><img src="/lam-an-logo.png" alt="Lam An"><h1>${store.status().mode==='loading'?'Đang tải quyền truy cập…':'Tài khoản chưa được cấp quyền'}</h1><p>${esc(store.status().message||'Nhờ admin thêm bạn vào quán và phân ca làm việc.')}</p><button class="primary" data-action="cloud-sync">Thử lại</button><button class="secondary" data-action="cloud-logout">Đăng xuất</button></main><div id="overlay-root"></div>`;return;}if(!admin()&&['team','audit'].includes(page))page='dashboard';if(!admin()&&!allowedShift(today,shift))shift=access().assignments.find(a=>a.day===today)?.shift||1;document.querySelector('#app').innerHTML=header()+`<main class="content">${page==='dashboard'?dashboard():page==='menu'?menuPage():page==='history'?history():page==='shifts'?shiftsPage():management()[page]||dashboard()}</main><footer class="main-footer">Được chăm chút cho những ngày bận rộn <span>✳ LAM AN COFFEE</span></footer></div><nav class="mobile-nav">${navItems().map(([id,t])=>`<button data-page="${id}" class="${page===id?'active':''}"><span>${icons[id]}</span>${t}</button>`).join('')}</nav><div id="overlay-root"></div>`;renderOverlay();renderCloudStatus();}
function editOrder(id){
 const order=db.orders.find(o=>o.id===id);
 if(!order||order.status==='cancelled'||!allowedShift(order.day,order.shift)){toast('Không có quyền sửa đơn này.');return;}
 editOriginal=structuredClone(order);draft=structuredClone(order);draft.editReason='';draft.settlement=null;category='Tất cả';query='';modal='order';renderOverlay();
}
function newOrder(){if(!allowedShift(today,shift)){toast('Bạn chưa được phân công ca này.');return;}if(closed()){toast('Ca này đã kết thúc. Hãy chọn một ca đang mở.');return;}draft={table:'1',customer:'',note:'',items:[]};category='Tất cả';query='';modal='order';renderOverlay();}
function renderOverlay(){let root=document.querySelector('#overlay-root');if(!modal){root.innerHTML='';return;}let body='';
if(modal==='cloud')body=cloudDialog();
if(modal==='password')body=`<form class="small-dialog" id="password-form"><div class="dialog-heading"><h2>Đổi mật khẩu</h2><button type="button" class="icon-button" data-action="dismiss" aria-label="Đóng">×</button></div><label>Mật khẩu mới<input name="password" type="password" required minlength="8" autocomplete="new-password"></label><button type="submit" class="primary full">Lưu mật khẩu</button></form>`;
if(modal==='order')body=`<div class="order-dialog"><div class="dialog-heading"><div><div class="eyebrow">${draft.id?'SỬA ĐƠN #'+esc(draft.code):'QUẦY BÁN HÀNG'} · CA ${draft.shift||shift}</div><h2>${draft.id?'Sửa đơn hàng':'Tạo đơn mới'}</h2></div><button class="icon-button" data-action="dismiss" aria-label="Đóng">×</button></div><div class="order-layout"><div class="order-menu"><div class="search-line"><div class="search-wrap"><span>⌕</span><input id="order-search" placeholder="Tìm món, ví dụ: cà phê sữa…" aria-label="Tìm món cho đơn" value="${esc(query)}"></div><button class="secondary" data-action="add-menu">＋ Thêm món</button></div><div id="order-results">${menuCards()}</div></div><div class="cart"><h3>Thông tin đơn hàng <span class="badge">Ca ${draft.shift||shift}</span></h3><label>Bàn / Số order<input id="table-input" value="${esc(draft.table)}" placeholder="Nhập số hoặc tên bàn" maxlength="60"></label><div class="table-picker">${Array.from({length:15},(_,i)=>`<button data-table="${i+1}" class="${draft.table==i+1?'selected':''}">${i+1}</button>`).join('')}</div><label>Tên khách hàng <small>(không bắt buộc)</small><input id="customer-input" value="${esc(draft.customer)}" placeholder="Ví dụ: Chị Linh" maxlength="100"></label>${draft.id?`<p class="note">Giữ nguyên ngày, ca và trạng thái thanh toán. Nếu ca đã kết, báo cáo sẽ được cập nhật và lưu dấu chỉnh sửa.${draft.status==='paid'?' Đơn đã thanh toán: hãy thu thêm hoặc hoàn lại tiền chênh lệch cho khách nếu tổng tiền thay đổi.':''}</p>`:''}<div class="cart-divider"></div><div id="cart-items">${cartItems()}</div><label>Ghi chú<input id="note-input" value="${esc(draft.note)}" placeholder="Ít đá, ít đường…" maxlength="300"></label><div id="paid-edit-fields">${paidEditFields()}</div><div id="cart-total">${cartTotal()}</div><button class="primary full" data-action="save-order">${draft.id?'Lưu thay đổi':'Lưu đơn hàng'} <span>↗</span></button><p class="cart-hint">${store.hasSession()?'Lưu trên máy và đồng bộ vào tài khoản':'Đơn được lưu trên thiết bị này'}</p></div></div></div>`;
if(modal==='menu')body=`<form id="menu-form" class="small-dialog"><div class="dialog-heading"><h2>${admin()?(editingMenu?'Chỉnh sửa món':'Thêm món mới'):'Đề xuất cập nhật menu'}</h2><button type="button" class="icon-button" data-action="back-menu" aria-label="Đóng">×</button></div><p class="muted">${admin()?'Món sẽ được lưu vào thực đơn để dùng cho lần sau.':'Admin duyệt đề xuất trước khi cập nhật thực đơn dùng chung.'}</p><label>Tên món<input name="name" required maxlength="100" value="${esc(editingMenu?.name||query)}" placeholder="Ví dụ: Cà phê kem"></label><label>Giá bán (VNĐ)<input name="price" required type="number" min="1000" max="10000000" step="1000" value="${editingMenu?.price||''}" placeholder="25000"></label><label>Nhóm món<select name="category">${[...new Set(db.menu.map(m=>m.category))].map(c=>`<option ${editingMenu?.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>${!admin()?`<label>Lý do đề xuất<input name="reason" required minlength="3" maxlength="300" placeholder="Vì sao cần cập nhật món?"></label>`:''}<button class="primary full" type="submit">${admin()?(editingMenu?'Lưu thay đổi':'Thêm vào thực đơn'):'Gửi đề xuất'}</button></form>`;
if(modal==='detail'){const o=db.orders.find(x=>x.id===detailId);if(!o){modal=null;return renderOverlay();}body=orderDetail(o);}
if(modal==='close-shift')body=closeShiftDialog();
if(modal==='cancel')body=cancelDialog();
if(modal==='adjust')body=adjustDialog();
root.innerHTML=`<div class="overlay" role="dialog" aria-modal="true" aria-label="${modal==='order'?'Tạo đơn mới':modal==='menu'?'Thông tin món':modal==='detail'?'Chi tiết đơn':modal==='cloud'?'Lưu trữ và đồng bộ':'Kết ca'}">${body}</div>`;
}
function paidEditFields(){
 if(draft?.status!=='paid')return '';
 const delta=total(draft)-total(editOriginal);
 return `<label>Lý do sửa đơn đã thanh toán<input id="edit-reason" maxlength="300" value="${esc(draft.editReason||'')}" placeholder="Bắt buộc, ví dụ: khách gọi thêm món"></label>${delta?`<div class="warning">${delta>0?'Cần thu thêm':'Cần hoàn lại'}: <b>${money(Math.abs(delta))}</b></div><label>Phương thức xử lý chênh lệch<select id="settlement-method"><option value="cash" ${draft.settlement?.method!=='transfer'?'selected':''}>Tiền mặt</option><option value="transfer" ${draft.settlement?.method==='transfer'?'selected':''}>Chuyển khoản</option></select></label><label class="check-label"><input id="settlement-confirmed" type="checkbox" ${draft.settlement?.confirmed?'checked':''}> Đã ${delta>0?'thu thêm':'hoàn lại'} đủ ${money(Math.abs(delta))} cho giao dịch này</label>`:''}`;
}
function orderDetail(o){
 return `<div class="small-dialog"><div class="dialog-heading"><div class="eyebrow">CHI TIẾT ĐƠN HÀNG</div><button class="icon-button" data-action="dismiss" aria-label="Đóng">×</button></div><h2>${esc(o.label)}</h2><p class="muted">#${o.code} · ${o.day.split('-').reverse().join('/')} · Ca ${o.shift}</p><span class="badge ${o.status==='paid'?'paid':''}">${o.status==='cancelled'?'Đã hủy':o.status==='paid'?'Đã thanh toán':'Đang phục vụ'}</span><div class="detail-items">${o.items.map(i=>`<div><span><b>${i.qty} × ${esc(i.name)}</b><small>${money(i.price)} / món</small></span><strong>${money(i.qty*i.price)}</strong></div>`).join('')}</div><p class="muted">Bàn: ${esc(o.table||'—')}<br>Tạo bởi: ${esc(o.createdByEmail||'Dữ liệu cũ')}${o.paidByEmail?`<br>Thu tiền: ${esc(o.paidByEmail)}`:''}${o.updatedByEmail?`<br>Sửa gần nhất: ${esc(o.updatedByEmail)} · ${new Date(o.updatedAt).toLocaleString('vi-VN')}`:''}</p>${o.note?`<p class="note">Ghi chú: ${esc(o.note)}</p>`:''}${o.cancelReason?`<p class="warning">Lý do hủy: ${esc(o.cancelReason)}${o.refundConfirmed?'<br>Đã ghi nhận hoàn tiền theo phương thức đã thu.':''}</p>`:''}${o.revisions?.length?`<details class="order-revisions"><summary>Lịch sử chỉnh sửa (${o.revisions.length})</summary>${[...o.revisions].reverse().map(r=>`<p><b>${esc(r.actorEmail||'Dữ liệu cũ')}</b><small>${new Date(r.at).toLocaleString('vi-VN')}</small>${esc(r.reason||'Chỉnh sửa thông tin')}<br>Trước sửa: ${money(total(r.before))}</p>`).join('')}</details>`:''}<div class="cart-grand"><span>${o.status==='cancelled'?'Giá trị đơn đã hủy':'Tổng thanh toán'}</span><strong>${money(total(o))}</strong></div>${o.status!=='cancelled'?`<button class="secondary full edit-order-button" data-edit-order="${o.id}">✎ Sửa đơn</button>${o.status==='open'||admin()?`<button class="secondary full danger-button" data-cancel-order="${o.id}">Hủy đơn</button>`:''}`:''}${o.status==='open'?paymentSection(o):o.status==='paid'?`<div class="payment-receipt"><span>Phương thức thanh toán</span><strong>${paymentLabel(o)}</strong></div><p class="cart-hint">Thanh toán lúc ${new Date(o.paidAt).toLocaleString('vi-VN')}</p>`:''}</div>`;
}
function paymentSection(o){return `<section class="payment-section"><h3>Phương thức thanh toán</h3><div class="payment-options" role="group" aria-label="Phương thức thanh toán"><button class="payment-option ${paymentMethod==='cash'?'selected':''}" data-payment-method="cash" aria-pressed="${paymentMethod==='cash'}"><span>▤</span>Tiền mặt<span class="payment-check">${paymentMethod==='cash'?'✓':''}</span></button><button class="payment-option ${paymentMethod==='transfer'?'selected':''}" data-payment-method="transfer" aria-pressed="${paymentMethod==='transfer'}"><span>▦</span>Chuyển khoản<span class="payment-check">${paymentMethod==='transfer'?'✓':''}</span></button></div>${paymentMethod==='transfer'?`<div class="transfer-panel"><span class="demo-label">QR MẪU · CHƯA DÙNG ĐỂ NHẬN TIỀN</span><img class="payment-qr" src="${PAYMENT_QR}" alt="Mã QR chuyển khoản giả lập, không dùng để chuyển tiền"><b>${money(total(o))}</b><p>Nội dung: <strong>LAM AN ${esc(o.code)}</strong></p><small>QR này chỉ để minh họa, chưa liên kết tài khoản ngân hàng. Chỉ xác nhận khi đã kiểm tra nhận tiền thực tế.</small></div>`:'<p class="payment-help">Nhận đủ tiền mặt từ khách trước khi xác nhận thanh toán.</p>'}<button class="primary full" data-pay="${o.id}">✓ Xác nhận đã thanh toán</button></section>`;}
